body.script:
        // Funzione per caricare il file XML
        function caricaXML() {
            fetch('frasi.xml')  // Percorso del tuo file XML
                .then(response => response.text())
                .then(str => {
                    let parser = new DOMParser();
                    let xmlDoc = parser.parseFromString(str, "text/xml");
                    mostraFrasi(xmlDoc);
                })
                .catch(error => console.log("Errore nel caricamento del file XML:", error));
        }

        // Funzione per mostrare le frasi
        function mostraFrasi(xmlDoc) {
            let frasi = xmlDoc.getElementsByTagName('frase');
            let currentDate = new Date();
            let contenutoDiv = document.getElementById('contenuto');

            // Iteriamo su tutte le frasi nel file XML
            for (let i = 0; i < frasi.length; i++) {
                let frase = frasi[i];
                let data = frase.getElementsByTagName('data')[0].textContent;
                let ora = frase.getElementsByTagName('ora')[0].textContent;

                // Creiamo un oggetto Date con la data e ora dell'XML
                let fraseDate = new Date(data + ' ' + ora);

                // Confrontiamo l'ora attuale con la data/ora della frase
                if (currentDate >= fraseDate) {
                    let trePeriodi = frase.getElementsByTagName('tre_periodi')[0].textContent;
                    let completa = frase.getElementsByTagName('completa')[0].textContent;

                    // Creiamo la struttura per la frase e il pulsante per "decifrarla"
                    let divFrase = document.createElement('div');
                    divFrase.classList.add('frase');
                    divFrase.innerHTML = `
${trePeriodi}Decifra`;
                    contenutoDiv.appendChild(divFrase);
                }
            }
        }

        // Funzione per svelare la frase completa
        function svelaFrase(completa) {
            alert(completa);  // Puoi usare un altro metodo per visualizzare la frase completa, come una finestra o un pop-up personalizzato
        }

        // Carica l'XML quando la pagina è pronta
        window.onload = caricaXML;
